    id   BIGINT       NOT NULL AUTO_INCREMENT,
    name VARCHAR(100) NOT NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uk_users_name (name)
);

INSERT IGNORE INTO users (name) VALUES ('alice'), ('bob');

